	[1000026] = {
		id = 1000026,
		roleTitle = "",
		roleName = "",
		showText = "墨丘利之星的变乱，被缇缇波芙以巫毒的小法术成功利用，进展十分顺利。\
九成以上的理事会守军，都如杂鱼般被缇缇波芙轻松游过了身旁，没有激起一丝波澜。\
或许这也是星命的显现——太阳系正在盼望理事卿的退场。",
		playType = 6,
		skipButton = 0,
