	[1000051014] = {
		id = 1000051014,
		roleTitle = "",
		roleName = "",
		showText = "如你所知，「复乐园理事会」推动了一项拆解水星的计划，以永久根除水逆问题。\
水星的本质，是一个带有硅酸盐外壳的铁金属球。为了改造金星的大气成分，理事会将水星上的镁、钠等金属大量开采、运往金星。\
工程旷日持久，工地上的人们也发展起了自己的文化。\
比如特定工种的家族继承、把工程器械作为成人礼物的习俗、在拆解作业场必须遵循的四十种迷信仪式……等等。",
		playType = 6,
		skipButton = 0,
		cutScenePath = "/Script/Engine.Texture2D'/Game/_Game/TP_New/StoryTree/Event_res/Event_1_26.Event_1_26'",
		playLoopPath = "",
		cameraPath = "",
		cutSceneStartFrame = 0,
		cameraStartFrame = 0,
		soundCue = "",
		NpcSpeak = "",
