	[1000066039] = {
		id = 1000066039,
		roleTitle = "",
		roleName = "",
		showText = "同时，你还打听了「中枢」的事。\
于是你这才知道，如今世界政府已被篡权，新成立的机构叫做「无尽全盛统合中枢」，简称「中枢」，现在与理事会并立为太阳系两极势力，分庭抗礼。\
虽然这件事可以说是近一年来太阳系的最大事件，人尽皆知，但你才复活了一周多，所以直到现在才听说了这个大新闻。",
		playType = 6,
		skipButton = 0,
		cutScenePath = "/Script/Engine.Texture2D'/Game/_Game/TP_New/StoryTree/Event_res/Event_1_30.Event_1_30'",
		playLoopPath = "",
		cameraPath = "",
		cutSceneStartFrame = 0,
		cameraStartFrame = 0,
		soundCue = "",
		NpcSpeak = "",
		mapPath = "",
		asyncEvaluation = 0,
		playMaskFade = "",
		next = 1000066040,
		options1 = "",
		options2 = "",
