	[1000098010] = {
		id = 1000098010,
		roleTitle = "",
		roleName = "",
		showText = "听了一会酒客的呓语，你明白了。\
为什么到处行骗已久的「比大更大师」，在「无序之都」却被当做小丑对待？\
这是因为「无序之都」理事会分部的头目，斋藤大佐，是一个「能沟通理事卿意志」的人。",
		playType = 6,
		skipButton = 0,
		cutScenePath = "/Script/Engine.Texture2D'/Game/_Game/TP_New/StoryTree/Event_res/Event_1_76.Event_1_76'",
		playLoopPath = "",
		cameraPath = "",
		cutSceneStartFrame = 0,
		cameraStartFrame = 0,
		soundCue = "",
		NpcSpeak = "",
