		options5 = "",
		options6 = "",
		bgmCue = "/Script/Engine.SoundCue'/Game/_Game/SoundEffects/BGM/City/Cue/SC_City_Bgm.SC_City_Bgm'",
		bgmParameter = "0|0|1|0.5|0.5",
		OptionBackgtound = "",
		TutorialId = 0,
	},
	[1000098011] = {
		id = 1000098011,
		roleTitle = "",
		roleName = "",
		showText = "斋藤大佐能够召唤理事卿的「机仆」——那套武装机甲的半身——然后声称自己从「机仆」那里，得到了理事卿的指示。\
「机仆降临」，是理事卿在太阳系的各分部，都无人能够做到的，绝无仅有的神迹。\
所以「无序之都」的理事会分部，是太阳系内仅有的，全员严重偏向「理事卿未死」这一说法的理事会分部。",
		playType = 6,
		skipButton = 0,
		cutScenePath = "/Script/Engine.Texture2D'/Game/_Game/TP_New/StoryTree/Event_res/Event_1_82.Event_1_82'",
		playLoopPath = "",
		cameraPath = "",
		cutSceneStartFrame = 0,
		cameraStartFrame = 0,
		soundCue = "",
		NpcSpeak = "",
		mapPath = "",
		asyncEvaluation = 0,
		playMaskFade = "",
		next = 1000098012,
		options1 = "",
		options2 = "",
		options3 = "",
