	[1000129] = {
		id = 1000129,
		roleTitle = "",
		roleName = "",
		showText = "在书架的每一层，法律杂志与古老的法典并排摆放。\
检查之后，都是装饰用的空壳。\
桌上有一本心理学书籍、几页散乱的笔记。笔记上草草地写着一些劝说技巧，和演讲时的提示语（配有精心设计的肢体语言）。但你没见到任何对法律条文的分析。",
		playType = 6,
