	},
	[1000135002] = {
		id = 1000135002,
		roleTitle = "",
		roleName = "",
		showText = "怪不得辩才姬刚才提出的所有方案，都不怎么运用智力。\
辩才姬对法律的了解，可能远不如至少知道一些交规的你。\
但她也有放之四海而皆准的小妙招，真是一劳永逸，以不变应万变……",
		playType = 6,
		skipButton = 0,
		cutScenePath = "/Script/Engine.Texture2D'/Game/_Game/TP_New/StoryTree/Event_res/20.20'",
